#ifndef __VENDOR_BEKEN_CHIPS_BK7258_HARDWARE_BK7258_MBOX_H
#define __VENDOR_BEKEN_CHIPS_BK7258_HARDWARE_BK7258_MBOX_H

#include <nuttx/config.h>

#include <stdbool.h>
#include <stddef.h>
