   301	
   302	static int flash_ipc_rx(FAR const struct bk7258_mb_wire_message *message,
   303	                        FAR uint8_t *ack_flags, FAR void *arg)
   304	{
   305	  UNUSED(arg);
   306	
   307	  /* Tell the peer its frame is handled and done (ACK_STATE_COMPLETE, the
   308	   * value mailbox_channel.c puts in ack_data1).  Answering 0 leaves the
   309	   * server's socket in "receive in process", and every later request comes
   310	   * back rejected: measured as ack status 0x52, i.e. route RX_BUSY (5) and
   311	   * api RX_BUSY (2) at once, with no reply frame at all.
   312	   */
   313	
   314	  if (ack_flags != NULL)
   315	    {
   316	      *ack_flags = 2u;
   317	    }
   318	
   319	  g_flash.rsp_cmd = bk7258_mb_header_cmd(message);
   320	  g_flash.rsp_user_cmd = message->crc8;
   321	  g_flash.rsp_status = (uint8_t)(message->payload_address >> 24);
   322	  g_flash.rsp_len = message->payload_length;
   323	  g_flash.rsp_buff = (FAR uint8_t *)(uintptr_t)message->reserved;
   324	
   325	  nxsem_post(&g_flash.done);
   326	  return OK;
   327	}
   405	static int flash_ipc_xfer(uint8_t cmd, uint8_t user_cmd,
