   582	int bk7258_flash_read(uint32_t address, FAR void *buffer, size_t len)
   583	{
   584	  FAR uint8_t *out = buffer;
   585	  int ret = OK;
   586	
   587	  if (!g_flash.connected || buffer == NULL || len == 0)
   588	    {
   589	      return -EINVAL;
   590	    }
   591	
   592	  nxmutex_lock(&g_flash.lock);
   593	
   594	  while (len > 0)
   595	    {
   596	      size_t chunk = len > FLASH_IPC_CHUNK ? FLASH_IPC_CHUNK : len;
   597	
   598	      memset((FAR void *)flash_request, 0, sizeof(struct flash_ipc_cmd_s));
   599	      (*flash_request).part_addr = flash_part_addr(address, 0);
   600	      (*flash_request).len = (uint16_t)chunk;
   601	
   602	      ret = flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_READ, (FAR void *)flash_request,
   603	                           sizeof(struct flash_ipc_cmd_s), FLASH_OP_TIMEOUT_MS);
   604	      if (ret < 0)
   605	        {
   606	          break;
   607	        }
   608	
   609	      if (g_flash.rsp_user_cmd != FLASH_CMD_READ ||
   610	          g_flash.rsp_len != sizeof(struct flash_ipc_cmd_s) ||
   611	          g_flash.rsp_buff == NULL)
   612	        {
   613	          ret = -EPROTO;
   614	          break;
   615	        }
   616	
   617	      {
   618	        FAR const struct flash_ipc_cmd_s *rsp =
   619	          (FAR const struct flash_ipc_cmd_s *)g_flash.rsp_buff;
   620	
   621	        if (rsp->ret_status != 0 || rsp->len != chunk || rsp->buff == NULL)
   622	          {
   623	            ret = -EIO;
   624	            break;
   625	          }
   626	
   627	        if (!flash_peer_ptr_ok(rsp->buff, chunk))
   628	          {
   629	            printf("flash: read payload at %p (%u bytes) is outside the "
   630	                   "regions this core maps; refusing the copy\n",
   631	                   rsp->buff, (unsigned int)chunk);
   632	            ret = -EFAULT;
   633	            break;
   634	          }
   635	
   636	        memcpy(out, rsp->buff, chunk);
   637	
   638	        if (flash_payload_crc32(out, chunk) != rsp->crc)
   639	          {
   640	            ret = -EBADMSG;
   641	            break;
   642	          }
   643	      }
