   343		memset(&cmd_buff, 0, sizeof(cmd_buff));
   344	
   345		if(recv_len != sizeof( cmd_buff))
   346		{
   347			mb_ipc_recv(handle, &user_cmd, NULL, 0, 0);  // data_buff == NULL or buff_len == 0 just discard all data.
   348	
   349			// if client wait_forever, then must send a response even if user_cmd == INVALID_USER_CMD_ID.
   350			// flash client does not wait forever, so only respond then cmd is valid.
   351			if(user_cmd != INVALID_USER_CMD_ID)
   352				flash_error_handler(handle, user_cmd);
   353	
   354			TRACE_E(TAG, "recv user_cmd=%d, data len failed! %d\r\n", user_cmd, recv_len);
   355	
   356			return;
   357		}
   358	
   359		recv_len = mb_ipc_recv(handle, &user_cmd, (u8 *)&cmd_buff, sizeof(cmd_buff), 0);
   360	
   361		if(recv_len != sizeof( cmd_buff))
   362		{
   363			// if client wait_forever, then must send a response even if user_cmd == INVALID_USER_CMD_ID.
   364			// flash client does not wait forever, so only respond then cmd is valid.
   365			if(user_cmd != INVALID_USER_CMD_ID)
   366				flash_error_handler(handle, user_cmd);
   367	
   368			TRACE_E(TAG, "recv user_cmd=%d, data len failed! %d\r\n", user_cmd, recv_len);
   369	
   370			return;
   371		}
   372	
   373		switch(user_cmd)
   374		{
   375			// flash driver cmds.
   376			// these flash driver cmds should be turned off when all APPs have been updated to use flash partition APIs.
   377			#if 1
   378			case FLASH_CMD_ERASE_SECTOR:
   379				flash_erase_handler(handle, &cmd_buff);
   380				break;
   381	
   382			case FLASH_CMD_READ:
   383				flash_read_handler(handle, &cmd_buff, connect_id);
   384				break;
   385	
   386			case FLASH_CMD_WRITE:
   387				flash_write_handler(handle, &cmd_buff);
   388				break;
