   205	/****************************************************************************
   206	 * Name: flash_part_addr
   207	 *
   208	 * Description:
   209	 *   Pack a flash offset into the server's part_id:8 / addr:24 word.
   210	 *
   211	 *   The address occupies bits 8-31, not 0-23.  Getting this wrong does not
   212	 *   produce an error: the server happily reads whatever address it was given,
   213	 *   so the symptom is data from the wrong place -- or, when the resulting
   214	 *   address is one the server will not serve, no reply at all, which on this
   215	 *   transport escalates into a chip reset (an unanswered transaction is
   216	 *   aborted, the link is quarantined and re-probed, and while it is probing
   217	 *   nothing else can be sent -- including the heartbeat the CP's 8-second
   218	 *   watchdog is waiting for).  Measured 2026-08-18 as a boot loop with
   219	 *   "IPC[1]heartbeat timeout" and "Assert at: mb_ipc_task:297".
   220	 *
   221	 ****************************************************************************/
   222	
   223	static inline uint32_t flash_part_addr(uint32_t address, uint8_t part_id)
   224	{
   225	  return ((address & 0x00ffffffu) << 8) | part_id;
   226	}
   227	
   228	/* CRC-32 over the payload bytes, in exactly the form the flash service uses.
   229	 *
   230	 * The polynomial is the usual reflected 0xedb88320, but the server calls it as
   231	 * calc_crc32(0, buf, len) (flash_server.c) -- no 0xffffffff seed and no final
   232	 * complement.  Seeding and complementing, which is what the same polynomial
   233	 * normally comes with, produces a different number for the same bytes: every
   234	 * read would then fail its check here as -EBADMSG, and every write would be
   235	 * rejected by the server, which re-computes this over the buffer it was handed
   236	 * and compares.  The store's own CRC (bk7258_kvdb.c) is a separate matter --
   237	 * nothing but this port reads it, so it keeps the seeded form.
   238	 */
   239	
   240	static uint32_t flash_payload_crc32(FAR const uint8_t *data, size_t len)
   241	{
   242	  uint32_t crc = 0;
   243	  size_t i;
   244	  int bit;
   245	
   246	  for (i = 0; i < len; i++)
   247	    {
   248	      crc ^= data[i];
   249	      for (bit = 0; bit < 8; bit++)
   250	        {
   251	          crc = (crc >> 1) ^ (0xedb88320u & (~(crc & 1u) + 1u));
   252	        }
   253	    }
   254	
   255	  return crc;
   256	}
   257	
   258	/* CRC-8 with polynomial 0x31, table-free.  mb_ipc puts this over the payload
   259	 * in cmd_data_crc8 and the receiver checks it (mb_ipc.c:1985); sending zero
   260	 * instead made the server drop every request, which looked like a timeout
   261	 * rather than a rejection.  Same table as cal_crc8_0x31(), computed rather
   262	 * than copied.
   263	 */
   264	
   265	static uint8_t flash_crc8(FAR const uint8_t *data, size_t len)
   266	{
   267	  uint8_t crc = 0x00;
   268	  size_t i;
   269	  int bit;
   270	
   271	  for (i = 0; i < len; i++)
   272	    {
   273	      crc ^= data[i];
   274	
   275	      for (bit = 0; bit < 8; bit++)
   276	        {
   277	          crc = (uint8_t)((crc & 0x80u) != 0 ?
   278	                          ((crc << 1) ^ 0x31u) : (crc << 1));
   279	        }
   280	    }
   281	
   282	  return crc;
   283	}
   284	
   285	static uint32_t flash_ipc_param1(uint8_t tag)
   286	{
   287	  uint32_t dst = IPC_FLASH_SERVER_PORT | (IPC_FLASH_SERVER_CPU << 6);
   288	  uint32_t src = IPC_FLASH_CLIENT_PORT | (IPC_FLASH_CLIENT_CPU << 6);
   289	
   290	  return dst | (src << 8) | ((uint32_t)tag << 16);
   291	}

